	private void RequestEditorRestart(bool toggleTheme)
	{
		if (restartRequested)
		{
			return;
		}
		restartRequested = true;
		restartWithThemeToggle = toggleTheme;
		FormClosed += RestartEditorAfterFormClosed;
		Action closeAction = Close;
		if (!this.BeginInvokeSafe(closeAction))
		{
			closeAction();
		}
	}

	private void CancelPendingRestart()
	{
		if (!restartRequested)
		{
			return;
		}
		FormClosed -= RestartEditorAfterFormClosed;
		restartRequested = false;
		restartWithThemeToggle = false;
		bool_21 = false;
	}

	private void RestartEditorAfterFormClosed(object sender, FormClosedEventArgs e)
	{
		FormClosed -= RestartEditorAfterFormClosed;
		if (!restartRequested)
		{
			return;
		}
		restartRequested = false;
		try
		{
			if (restartWithThemeToggle)
			{
				TDark.ToggleTheme();
			}
			using (Process process = Process.Start(new ProcessStartInfo
			{
				FileName = Application.ExecutablePath,
				Arguments = "-restarted",
				WorkingDirectory = Application.StartupPath,
				UseShellExecute = false
			}))
			{
				if (process == null)
				{
					throw new InvalidOperationException(GetThemeLocalizedText("ui.restart.launch_failed", "Não foi possível reiniciar o editor automaticamente.", "The editor could not restart automatically."));
				}
			}
		}
		catch (Exception ex)
		{
			DKBox.Show(
				GetThemeLocalizedText("ui.restart.launch_failed", "Não foi possível reiniciar o editor automaticamente.", "The editor could not restart automatically.") + Environment.NewLine + ex.Message,
				GetThemeLocalizedText("ui.restart.title", "Reinicialização necessária", "Restart required"),
				MessageBoxButtons.OK,
				MessageBoxIcon.Error);
		}
		finally
		{
			restartWithThemeToggle = false;
			bool_21 = false;
		}
	}

